#!/usr/bin/env python3
"""Render docs/observability/metric-registry.md: every metric this service
emits, from two sources of truth.

  * The Platform Observability Registry shipped with the pinned
    platform-gincommon (internal/obsregistry/registry.json): every Tier 1
    metric owned by a platform library this service links (platform-gincommon
    HTTP server, platform-events, platform-pgcommon), and the Tier 2 domain-shared
    entries.
  * A real /metrics scrape (TestStandard_LibrariesShareRegistryCollectors,
    which records one sample on every collector this service owns): every
    Tier 3 workflow_execution_service_* metric with its type, labels and
    help text.

Usage: metrics-inventory.py <registry.json> <scrape.txt> <gincommon-version>
Writes the Markdown to stdout. Run through `make metrics-inventory`; CI
fails when the committed file differs (.github/scripts/metricslint.sh).
"""
import json
import re
import sys

LIBRARIES = ("platform-gincommon", "platform-events", "platform-pgcommon")
# Series-level labels that are not part of a metric's own label set.
IGNORED_LABELS = {"domain", "service", "environment", "le", "quantile"}
SERVICE_PREFIX = "workflow_execution_service_"
SERVICE = "workflow-execution-service"
EVENTS_EMITTED = {"platform_library_info"}


def md(text):
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def parse_scrape(path):
    """Return {family: {"type", "help", "labels"}} from Prometheus text."""
    families = {}
    for line in open(path, encoding="utf-8"):
        line = line.rstrip("\n")
        if line.startswith("# HELP "):
            name, _, help_text = line[len("# HELP "):].partition(" ")
            families.setdefault(name, {"labels": set()})["help"] = help_text
        elif line.startswith("# TYPE "):
            name, _, mtype = line[len("# TYPE "):].partition(" ")
            families.setdefault(name, {"labels": set()})["type"] = mtype
        elif line and not line.startswith("#"):
            m = re.match(r"([a-zA-Z_:][a-zA-Z0-9_:]*)(\{([^}]*)\})?", line)
            if not m:
                continue
            series = m.group(1)
            family = series
            for suffix in ("_bucket", "_sum", "_count"):
                if series.endswith(suffix) and series[: -len(suffix)] in families:
                    family = series[: -len(suffix)]
            labels = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="', m.group(3) or "")
            families.setdefault(family, {"labels": set()})["labels"].update(
                label for label in labels if label not in IGNORED_LABELS
            )
    return families


def labels_cell(entry):
    labels = entry.get("labels") or []
    if not labels:
        return "-"
    cell = ", ".join(f"`{label}`" for label in labels)
    for label, values in sorted((entry.get("label_values") or {}).items()):
        cell += f"<br>`{label}` ∈ " + ", ".join(f"`{v}`" for v in values)
    return cell


def type_cell(entry):
    mtype = entry.get("type", "")
    if mtype == "histogram" and entry.get("buckets"):
        return f"histogram ({entry['buckets']})"
    return mtype


def main():
    registry_path, scrape_path, gincommon_version = sys.argv[1:4]
    registry = json.load(open(registry_path, encoding="utf-8"))
    scrape = parse_scrape(scrape_path)
    entries = registry["metrics"]

    out = []
    w = out.append
    w("# Metric inventory: workflow-execution-service")
    w("")
    w("<!-- Generated by `make metrics-inventory` (.github/scripts/metrics-inventory.py) from the")
    w(f"     Platform Observability Registry in platform-gincommon {gincommon_version} and a real /metrics")
    w("     scrape of this service. Do not edit; CI fails when this file is out of date. -->")
    w("")
    w("Every series carries the centrally injected const labels `domain` (`workflow`), `service` "
      "(`workflow-execution-service`) and `environment`. The tables list each metric's own labels only. "
      "Status is the registry's: `approved`, or `proposed` (awaiting observability-governance "
      "ratification). Tier 3 metrics are this service's own and need no registry entry. "
      "See [README.md](README.md) for how the tiers are built and enforced.")
    w("")

    w("## Tier 1: platform-shared metrics (emitted by the platform libraries)")
    w("")
    w("This service does not construct these. The libraries record them on the shared "
      "registry (`gincommon.MetricsRegisterer()`), and the service only builds the collector "
      "a library adopts (`gincommon.NewSharedCounterVec` / `NewSharedHistogramVec`) where it "
      "also records into it.")
    w("")
    w("| Metric | Emitted by | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|---|")
    for entry in entries:
        if entry.get("tier") != "platform" or entry.get("owner") not in LIBRARIES:
            continue
        if entry["name"].startswith("platform_grpc_"):
            continue
        if entry.get("owner") == "platform-events" and entry["name"] not in EVENTS_EMITTED:
            continue
        w(f"| `{entry['name']}` | {entry['owner']} | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")

    w("The outbox runner of the API server also records the platform-events outbox and publisher "
      "series (`platform_outbox_*`, `platform_messages_published_total`, `platform_dlq_messages_total`, "
      "`platform_dependency_request_seconds`) once it runs; they appear in a live scrape and not in the "
      "unit-test scrape this table is built from. The consumer metrics belong to the shared consumer.")
    w("")
    w("## Tier 2: workflow domain-shared metrics")
    w("")
    w("The registry defines no `workflow_*` metrics yet, so none are emitted.")
    w("")

    w("## Tier 3: service-specific metrics (`workflow_execution_service_*`)")
    w("")
    w("| Metric | Type | Labels | Meaning |")
    w("|---|---|---|---|")
    for name in sorted(n for n in scrape if n.startswith(SERVICE_PREFIX)):
        fam = scrape[name]
        labels = ", ".join(f"`{label}`" for label in sorted(fam["labels"])) or "-"
        w(f"| `{name}` | {fam.get('type', '')} | {labels} | {md(fam.get('help'))} |")
    w("")
    print("\n".join(out))


if __name__ == "__main__":
    main()
